import { Haau3 } from "@haau3/sdk";

const haau3 = new Haau3(); // reads HAAU3_API_KEY
const results = await haau3.batch((b) => [
  b.codeSystemLookup({ system: "http://loinc.org", code: "2345-7", property: "SHORTNAME" }),
  b.codeSystemLookup({ system: "http://loinc.org", code: "8867-4", property: "SHORTNAME" }),
  b.listInsurancePlanCounties({ state: "DE" }),
]);
for (const result of results) console.log(result.ok ? result.status : result.error.message);

import { Haau3 } from "@haau3/sdk";

const haau3 = new Haau3(); // reads HAAU3_API_KEY
// Open appointment slots of one provider, found by NPI, each with its schedule, location and provider.
const page = await haau3.searchSlotWithIncludes({
  "provider-identifier": "http://hl7.org/fhir/sid/us-npi|2900000227",
  _count: 1,
});
const [view] = haau3.slotViews(page);
// A name's text, or its given and family names when the publisher sent no text.
const name = view?.practitioners[0]?.name?.[0];
console.log(
  view
    ? {
        start: view.slot.start,
        practitioner: name?.text ?? [name?.given?.join(" "), name?.family].filter(Boolean).join(" "),
        location: view.locations[0]?.name,
        bookingLink: view.bookingLink,
      }
    : "No open slots matched.",
);

